package connect

import (
	"fmt"
	"strings"
)

// ResultOf inspects a Hex / Polygon board and reports the winner.
//
// Player 'O' plays from the top edge to the bottom edge, player 'X' plays
// from the left edge to the right edge. The returned string is "O", "X" or
// "" when nobody has won yet.
func ResultOf(lines []string) (string, error) {
	board, err := parseBoard(lines)
	if err != nil {
		return "", err
	}

	if board.connected('O') {
		return "O", nil
	}
	if board.connected('X') {
		return "X", nil
	}
	return "", nil
}

type board [][]byte

func parseBoard(lines []string) (board, error) {
	b := make(board, len(lines))
	for i, line := range lines {
		row := []byte(strings.TrimSpace(line))
		// Cells may be separated by whitespace; strip it to get the raw cells.
		cells := make([]byte, 0, len(row))
		for _, c := range row {
			switch c {
			case ' ', '\t':
			case '.', 'O', 'X':
				cells = append(cells, c)
			default:
				return nil, fmt.Errorf("invalid character %q on line %d", c, i+1)
			}
		}
		b[i] = cells
	}
	return b, nil
}

// at returns the contents of cell (r, c) or 0 when out of range.
func (b board) at(r, c int) byte {
	if r < 0 || r >= len(b) {
		return 0
	}
	row := b[r]
	if c < 0 || c >= len(row) {
		return 0
	}
	return row[c]
}

// neighbors enumerates the six adjacent cells of (r, c) for a board drawn as
// a parallelogram (rows shifted to the right as the row index grows).
func neighbors(r, c int) [6][2]int {
	return [6][2]int{
		{r, c - 1},
		{r, c + 1},
		{r - 1, c},
		{r - 1, c + 1},
		{r + 1, c},
		{r + 1, c - 1},
	}
}

// connected reports whether player p has a chain of its stones joining its two
// goal edges. For 'O' those are the top and bottom rows, for 'X' the leftmost
// and rightmost columns.
func (b board) connected(p byte) bool {
	if len(b) == 0 {
		return false
	}

	var start [][2]int
	for r := range b {
		for c := range b[r] {
			if b[r][c] != p {
				continue
			}
			if p == 'O' {
				if r == 0 {
					start = append(start, [2]int{r, c})
				}
			} else if c == 0 {
				start = append(start, [2]int{r, c})
			}
		}
	}
	if len(start) == 0 {
		return false
	}

	visited := make([][]bool, len(b))
	for r := range b {
		visited[r] = make([]bool, len(b[r]))
	}

	queue := make([][2]int, 0, len(start))
	for _, s := range start {
		visited[s[0]][s[1]] = true
		queue = append(queue, s)
	}

	for len(queue) > 0 {
		cell := queue[0]
		queue = queue[1:]
		r, c := cell[0], cell[1]

		if p == 'O' && r == len(b)-1 {
			return true
		}
		if p == 'X' && c == len(b[r])-1 {
			return true
		}

		for _, n := range neighbors(r, c) {
			nr, nc := n[0], n[1]
			if nr < 0 || nr >= len(b) || nc < 0 || nc >= len(b[nr]) {
				continue
			}
			if visited[nr][nc] || b[nr][nc] != p {
				continue
			}
			visited[nr][nc] = true
			queue = append(queue, [2]int{nr, nc})
		}
	}
	return false
}
